<!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><?php wp_head(); ?></head><body <?php body_class(); ?>><?php wp_body_open(); ?><header class="nv-header"><div class="nv-wrap nv-nav"><a class="nv-brand" href="<?php echo esc_url(home_url('/')); ?>">NVConsult</a><button class="nv-menu-toggle" type="button" aria-expanded="false" aria-controls="nv-primary-menu"><span aria-hidden="true">☰</span><span class="screen-reader-text"><?php esc_html_e('Menu','nvconsult'); ?></span></button><nav id="nv-primary-menu" class="nv-menu" aria-label="<?php esc_attr_e('Primary navigation','nvconsult'); ?>"><?php if(has_nav_menu('primary')){wp_nav_menu(['theme_location'=>'primary','container'=>false,'items_wrap'=>'%3$s','fallback_cb'=>false]);}else{?><a href="<?php echo esc_url(home_url('/study/')); ?>">Study Abroad</a><a href="<?php echo esc_url(home_url('/jobs/')); ?>">Jobs Abroad</a><a href="<?php echo esc_url(home_url('/scholarships/')); ?>">Scholarships</a><a href="<?php echo esc_url(home_url('/internships/')); ?>">Internships</a><?php } ?></nav><a class="nv-btn nv-portal-button" href="<?php echo esc_url(nvconsult_theme_url('applicant-portal')); ?>"><?php esc_html_e('Applicant Portal','nvconsult'); ?></a></div></header><main id="content"><script>document.addEventListener('DOMContentLoaded',()=>{const b=document.querySelector('.nv-menu-toggle'),m=document.getElementById('nv-primary-menu');if(!b||!m)return;b.addEventListener('click',()=>{const o=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!o));m.classList.toggle('is-open',!o)})});</script>
